import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))
    w = int(next(iterator))

    grid = []
    for _ in range(n):
        row = []
        for _ in range(m):
            row.append(int(next(iterator)))
        grid.append(row)

    INF = float('inf')
    dist = [[INF] * m for _ in range(n)]

    # BFS for walking without portals
    q = deque()
    dist[0][0] = 0
    q.append((0, 0))

    min_portal_cost = INF
    min_portal_pos = None

    while q:
        r, c = q.popleft()

        if r == n - 1 and c == m - 1:
            continue

        current_dist = dist[r][c]

        # Check if current cell has a portal
        if grid[r][c] > 0:
            if current_dist + grid[r][c] < min_portal_cost:
                min_portal_cost = current_dist + grid[r][c]
                min_portal_pos = (r, c)

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                if grid[nr][nc] != -1:
                    new_dist = current_dist + w
                    if new_dist < dist[nr][nc]:
                        dist[nr][nc] = new_dist
                        q.append((nr, nc))

    # Calculate minimum time using portals
    # We need the minimum cost to reach any portal from start
    # and the minimum cost to reach any portal from end (reverse BFS)

    # First, find min cost to reach any portal from start
    min_from_start = INF
    for r in range(n):
        for c in range(m):
            if grid[r][c] > 0 and dist[r][c] != INF:
                cost = dist[r][c] + grid[r][c]
                if cost < min_from_start:
                    min_from_start = cost

    # Now do BFS from end to find min cost to reach any portal from end
    dist_end = [[INF] * m for _ in range(n)]
    q_end = deque()
    dist_end[n-1][m-1] = 0
    q_end.append((n-1, m-1))

    min_to_end = INF

    while q_end:
        r, c = q_end.popleft()

        if grid[r][c] > 0:
            cost = dist_end[r][c] + grid[r][c]
            if cost < min_to_end:
                min_to_end = cost

        directions = [(-1, 0), (1, 0) , (0, -1), (0, 1)]
        for Dr, Dc in directions:
            nr, nc = r + Dr, c + Dc
            if 0 <= nr < n and 0 <= nc < n:
                if grid[nr][nc] != -1:
                     new_dist = dist_end[r][c] + w
                     if new_dist < dist_end[nr][nc]:
                         dist_end[nr][nc] = new_dist
                         q_end.append((nr, nc))

    ans = dist[n-1][m-1]

    if min_from_start != INF and min_to_end != INF:
        ans = min(ans, min_from_start + min_to_end)

    if ans == INF:
        print("-1")
    else:
        print(ans)

solve()
